        d=(B[1]-C[1])*(A[0]-C[0])+(C[0]-B[0])*(A[1]-C[1])
        if abs(d)<1e-9: continue
        l1=((B[1]-C[1])*(x-C[0])+(C[0]-B[0])*(y-C[1]))/d
        l2=((C[1]-A[1])*(x-C[0])+(A[0]-C[0])*(y-C[1]))/d
        l3=1-l1-l2
        if min(l1,l2,l3)>=-1e-6: r.append(l1*A[2]+l2*B[2]+l3*C[2])
    return r
for pname,PW,_ in pads:
    if not pname.startswith('collision_pad'): continue
    cx=sum(p[0] for p in PW)/len(PW); cy=sum(p[1] for p in PW)/len(PW); top=max(p[2] for p in PW)
    res={}
    for dx in range(-50,51,10):
        for dy in range(-90,91,15):
            for n,W,t in coll:
                for z in hits(cx+dx,cy+dy,W,t):
                    if top-15<z<top+15: res.setdefault(round(z,3),0); res[round(z,3)]+=1
    print(pname,'top',round(top,3),'station z near:',sorted(res.items()))
