import sys,math; sys.path.insert(0,'/tmp/ana'); from dae import load
import dae, xml.etree.ElementTree as ET
fn=sys.argv[1]
objs=load(fn)
# get loc matrices
ns='{http://www.collada.org/2005/11/COLLADASchema}'
t=ET.parse(fn).getroot(); locs=[]
def walk(n,M):
    N=[r[:] for r in M]
    for el in n:
        tag=el.tag.split('}')[1]
        if tag=='matrix':
            v=list(map(float,el.text.split())); L=[v[i*4:i*4+4] for i in range(4)]
            N=[[sum(N[i][k]*L[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
        elif tag in('translate','rotate','scale'): print('WARN',tag)
    if n.get('name','').startswith('loc_'): locs.append((n.get('name'),N))
    for c in n.findall(ns+'node'): walk(c,N)
I=[[1 if i==j else 0 for j in range(4)] for i in range(4)]
for vs in t.iter(ns+'visual_scene'):
    for n in vs.findall(ns+'node'): walk(n,I)
pads=[(n,W) for n,W,_ in objs if n.startswith('collision_pad')]
for ln,N in locs:
    o=[N[i][3] for i in range(3)]; up=[N[i][1] for i in range(3)]; l=math.sqrt(sum(u*u for u in up)); up=[u/l for u in up]
    best=None
    for pn,W in pads:
        c=[sum(w[i] for w in W)/len(W) for i in range(3)]
        # lateral distance
        d=[c[i]-o[i] for i in range(3)]; h=sum(d[i]*up[i] for i in range(3)); lat=math.sqrt(max(0,sum(x*x for x in d)-h*h))
        top=max(sum((w[i]-o[i])*up[i] for i in range(3)) for w in W)
        if best is None or lat<best[0]: best=(lat,pn,top)
    print(ln, best[1], 'lat %.2f padtop-loc %.3f'%(best[0],best[2]))
